#!/bin/bash
# Snapshot the CoulN7 workspace sources into numerics/n7_interval/lean/ (a Lake workspace root):
#   CoulN7/**          every module < 100 kB verbatim (hand-written modules, minorants, specs, check assemblies);
#                      the large generated data/check modules are regenerated by gen/regen_all.sh (byte-identical);
#   LogLean/MinorCore.lean, ThomsonGen/{Generic,Cert}/*.lean   the stored (non-upstream) dependencies;
#   ThomsonGen/scripts/, regen.sh                              regeneration of the upstream-derived modules;
#   lakefile.toml (defaultTargets = ["CoulN7"]), lean-toolchain, lake-manifest.json, comparator_coul.json, scripts/;
#   SHA256SUMS                 sha256 of all 98 CoulN7 modules + the stored dependencies;
#   upstream_regenerated.sha256  sha256 of the 26 regenerated upstream modules in the import closure.
# Source workspace: $COULN7_LEAN (default: the Mac build workspace).
set -euo pipefail
P=${COULN7_LEAN:-$HOME/claude_projects/thomson-n7-log-macbuild/lean}; S=$(cd "$(dirname "$0")/.." && pwd)
cd $P
find CoulN7 -name "*.lean" -size -100k | while read f; do mkdir -p $S/$(dirname $f); cp $f $S/$f; done
STORED="LogLean/MinorCore.lean ThomsonGen/Generic/Energy.lean ThomsonGen/Generic/Glue.lean ThomsonGen/Cert/NBlk.lean ThomsonGen/Cert/NBlkCap.lean ThomsonGen/Cert/Split.lean"
for f in $STORED; do mkdir -p $S/$(dirname $f); cp $f $S/$f; done
mkdir -p $S/ThomsonGen/scripts/verbatim
cp ThomsonGen/scripts/{split.py,generated.sha256,gen_roots.txt,scan_upstream.py} $S/ThomsonGen/scripts/
cp ThomsonGen/scripts/verbatim/*.txt $S/ThomsonGen/scripts/verbatim/
cp regen.sh $S/
{ find CoulN7 -name "*.lean" | sort; for f in $STORED; do echo $f; done; } | xargs shasum -a 256 > $S/SHA256SUMS
rm -f $S/CoulN7/SHA256SUMS $S/CoulN7/lakefile_fragment.toml
# 26 regenerated upstream modules of the closure (everything in ThomsonGen/ imported by CoulN7 and not stored)
python3 - "$P" > $S/upstream_regenerated.sha256 <<'PY'
import os, re, sys, hashlib
root = sys.argv[1]; stored = {"ThomsonGen/Generic/Energy.lean", "ThomsonGen/Generic/Glue.lean", "ThomsonGen/Cert/NBlk.lean",
                             "ThomsonGen/Cert/NBlkCap.lean", "ThomsonGen/Cert/Split.lean"}
seen, st = set(), [os.path.join(dp, f)[len(root) + 1:] for dp, _, fs in os.walk(os.path.join(root, "CoulN7")) for f in fs if f.endswith(".lean")]
while st:
    p = st.pop()
    if p in seen: continue
    seen.add(p)
    for l in open(os.path.join(root, p)):
        m = re.match(r"import (ThomsonGen|LogLean|CoulN7)(\S*)", l)
        if m: st.append((m.group(1) + m.group(2)).replace(".", "/") + ".lean")
for p in sorted(x for x in seen if x.startswith("ThomsonGen/") and x not in stored):
    print(hashlib.sha256(open(os.path.join(root, p), "rb").read()).hexdigest() + "  " + p)
PY
echo "snapshot: $(find $S/CoulN7 -name '*.lean' | wc -l) CoulN7 files, $(wc -l < $S/SHA256SUMS) checksums, $(wc -l < $S/upstream_regenerated.sha256) upstream-regenerated checksums"
